public sealed record ReviewReceiptResult(
    bool Created,
    string Status,
    ReviewOutcome? Outcome,
    string? ReceiptPath,
    long? ReceiptSize,
    string? ReceiptSha256,
    string? WorkflowPath,
    long? WorkflowSize,
    string? WorkflowSha256,
    bool HumanVisualAuthority,
    bool RuntimeAuthority,
    bool PromotionAuthority);

public enum CommandExitCode
{
    Success = 0,
    GeneralFailure = 1,
    UsageError = 2,
    SecurityRefusal = 3,
    ValidationFailure = 4,
    Cancelled = 5
}

public sealed record CommandDescriptor(
    string Name,
    string Description,
    string SchemaVersion,
    bool Mutates,
    ImmutableArray<GameEdition> SupportedGames,
    ImmutableArray<string> Limitations);

