    private static readonly ImmutableDictionary<string, ImmutableArray<string>> LedgerMap =
        new Dictionary<string, ImmutableArray<string>>(StringComparer.OrdinalIgnoreCase)
        {
            ["gui"] = ["P12-001"],
            ["facegen bake-all"] = ["P12-002"],
            ["facegen build-geom"] = ["P12-003"],
            ["facegen diagnose"] = ["P12-004"],
            ["capabilities"] = ["P12-005"],
            ["schema export"] = ["P12-006"],
            ["package build"] = ["P12-007"],
            ["package inspect"] = ["P12-007"],
            ["package verify"] = ["P12-007"],
            ["package archive"] = ["P12-007"],
            ["pipeline preset-to-npc"] = ["P12-007"],
            ["npc create-from-preset"] = ["P12-007"],
            ["npc create-from-jslot"] = ["P12-007"]
        }.ToImmutableDictionary(StringComparer.OrdinalIgnoreCase);

    public static ImmutableArray<string> LedgerIdsFor(string commandName) =>
        LedgerMap.TryGetValue(commandName, out var ids) ? ids : [];

    private static CommandDescriptor Descriptor(string name, string description, bool mutates, string? limitation = null) =>
        new(name, description, "1", mutates,
            ImmutableArray.Create(GameEdition.Fallout4, GameEdition.SkyrimSpecialEdition),
            ImmutableArray.Create(limitation ?? "M1 shell: feature implementation is introduced by later milestones."));

    private static CommandDescriptor SkyrimDescriptor(
        string name,
        string description,
        bool mutates,
        string limitation) =>
        new(
            name,
            description,
            "1",
            mutates,
            ImmutableArray.Create(
                GameEdition.SkyrimSpecialEdition),
            ImmutableArray.Create(limitation));
}
